import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';
import { assertLock } from './wire-fixtures.mjs';

export const hash = (bytes) => createHash('sha256').update(bytes).digest('hex');
export async function rawCommand(argv, options = {}) {
  const child = spawn(argv[0], argv.slice(1), { cwd: options.cwd, stdio: ['ignore', 'pipe', 'pipe'] });
  const stdout = [], stderr = []; let error, bytes = 0;
  const timer = setTimeout(() => { error = 'command deadline'; child.kill('SIGKILL'); }, options.timeout ?? 30000);
  const collect = (target) => (b) => {
    bytes += b.length;
    if (bytes <= (2 << 20)) target.push(b);
    else { error = 'command output limit'; child.kill('SIGKILL'); }
  };
  child.stdout.on('data', collect(stdout)); child.stderr.on('data', collect(stderr));
  child.on('error', (e) => { error = e.message; });
  const [exit, signal] = await new Promise((resolve) => child.once('close', (...args) => resolve(args)));
  clearTimeout(timer);
  return { argv, cwd: options.cwd ?? process.cwd(), exit, signal, error,
    stdout: Buffer.concat(stdout).toString(), stderr: Buffer.concat(stderr).toString() };
}
export async function command(record, argv, options = {}) {
  const result = await rawCommand(argv, options);
  (record.commands ??= []).push(result);
  assert.equal(result.error, undefined, result.error);
  assert.equal(result.exit, 0, `${argv[0]}: ${result.stderr}`);
  return Buffer.from(result.stdout);
}
export async function build(directory, record) {
  assertLock();
  const pins = JSON.parse(fs.readFileSync('evidence/sprint05a-b/source-01/sources.json'));
  const upstream = path.join(directory, 'upstream');
  fs.mkdirSync(upstream);
  record.upstream = [];
  for (const name of ['include/llhttp.h', 'src/api.c', 'src/http.c', 'src/llhttp.c', 'LICENSE-MIT']) {
    const pin = pins.downloads.find((p) => p.name === `llhttp/${name}`);
    assert.ok(pin.url.includes('/816485216511b86459b2e6478190e14c38c14891/'));
    const cache = path.resolve('.local/sprint05b-a-sources', path.basename(name));
    fs.mkdirSync(path.dirname(cache), { recursive: true });
    let bytes = fs.existsSync(cache) ? fs.readFileSync(cache) : null;
    if (!bytes || hash(bytes) !== pin.sha256) {
      await command(record, ['curl', '--fail', '--silent', '--show-error', '--location',
        '--proto', '=https', '--proto-redir', '=https', '--tlsv1.2', '--connect-timeout', '10',
        '--max-time', '30', '--max-filesize', '1048576', '--output', cache + '.download', pin.url]);
      bytes = fs.readFileSync(cache + '.download');
      assert.equal(hash(bytes), pin.sha256);
      fs.mkdirSync(path.dirname(cache), { recursive: true });
      fs.writeFileSync(cache, bytes, { mode: 0o600 });
      fs.unlinkSync(cache + '.download');
    }
    assert.equal(hash(bytes), pin.sha256);
    fs.writeFileSync(path.join(upstream, path.basename(name)), bytes);
    record.upstream.push({ name, url: pin.url, sha256: pin.sha256, bytes: bytes.length });
  }
  const include = process.env.AEGIS_NODE_INCLUDE ?? path.resolve(path.dirname(process.execPath), '../include/node');
  assert.ok(fs.existsSync(path.join(include, 'node_api.h')), 'use the installed Node headers');
  record.compiler = (await command(record, ['cc', '--version'])).toString().split('\n')[0];
  record.nodeApiHeader = { file: path.join(include, 'node_api.h'), sha256: hash(fs.readFileSync(path.join(include, 'node_api.h'))) };
  const output = path.join(directory, 'llhttp.node');
  await command(record, ['cc', '-std=c11', '-Wall', '-Wextra', '-Werror', '-fsyntax-only',
    `-I${include}`, `-I${upstream}`, 'spikes/envoy/sprint05b-llhttp-addon.c']);
  record.buildArgv = ['cc', '-std=c11', '-O2', '-shared', '-fPIC', '-Wall', '-Werror',
    `-I${include}`, `-I${upstream}`, 'spikes/envoy/sprint05b-llhttp-addon.c',
    ...['api.c', 'http.c', 'llhttp.c'].map((f) => path.join(upstream, f)), '-o', output];
  await command(record, record.buildArgv);
  record.addonSha256 = hash(fs.readFileSync(output));
  const addon = createRequire(import.meta.url)(output);
  assert.equal(addon.llhttpVersion, '9.4.4');
  record.native = { version: addon.llhttpVersion, stateBytes: addon.stateBytes, maxFeedBytes: addon.maxFeedBytes };
  return addon;
}

/* Isolated feasibility binding: unchanged llhttp owns every framing boundary. */
#include <node_api.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "llhttp.h"

#define MAX_FEED 16384u
#define MAX_WIRE (32u * 1024u * 1024u)
#define MAX_BODY (8u * 1024u * 1024u)
#define MAX_META 16384u
#define MAX_TARGET 2048u
#define MAX_FIELDS 128u
#define MAX_MESSAGES 256u

typedef struct { size_t name, name_len, value, value_len; } field;
typedef struct {
  llhttp_t parser;
  llhttp_settings_t settings;
  uint64_t wire;
  size_t body, meta, target_len, fields, initial_fields;
  char metadata[MAX_META], target[MAX_TARGET];
  field headers[MAX_FIELDS];
  unsigned messages, calls;
  bool complete, headers_ready, paused, terminal, response, head;
} state;
static unsigned live;

static int limit(llhttp_t *p) {
  llhttp_set_error_reason(p, "bounded ingress limit"); return HPE_USER;
}
static int begin(llhttp_t *p) {
  state *s = p->data;
  s->body = s->meta = s->target_len = s->fields = s->initial_fields = 0;
  s->headers_ready = false;
  memset(&s->headers[0], 0, sizeof(field));
  return s->messages >= MAX_MESSAGES ? limit(p) : 0;
}
static int target(llhttp_t *p, const char *at, size_t n) {
  state *s = p->data;
  if (n > MAX_TARGET - s->target_len) return limit(p);
  memcpy(s->target + s->target_len, at, n); s->target_len += n; return 0;
}
static int field_name(llhttp_t *p, const char *at, size_t n) {
  state *s = p->data;
  if (s->fields >= MAX_FIELDS || n > MAX_META - s->meta) return limit(p);
  field *f = &s->headers[s->fields];
  if (!f->name_len) f->name = s->meta;
  memcpy(s->metadata + s->meta, at, n); s->meta += n; f->name_len += n; return 0;
}
static int field_value(llhttp_t *p, const char *at, size_t n) {
  state *s = p->data;
  if (s->fields >= MAX_FIELDS || n > MAX_META - s->meta) return limit(p);
  field *f = &s->headers[s->fields];
  if (!f->value_len) f->value = s->meta;
  memcpy(s->metadata + s->meta, at, n); s->meta += n; f->value_len += n; return 0;
}
static int field_done(llhttp_t *p) {
  state *s = p->data;
  if (s->fields >= MAX_FIELDS) return limit(p);
  s->fields++;
  if (s->fields < MAX_FIELDS) memset(&s->headers[s->fields], 0, sizeof(field));
  return 0;
}
static int headers_done(llhttp_t *p) {
  state *s = p->data;
  s->initial_fields = s->fields;
  if (s->response) return s->head ? 1 : 0;
  s->headers_ready = true; return HPE_PAUSED;
}
static int body(llhttp_t *p, const char *at, size_t n) {
  (void) at; state *s = p->data;
  if (n > MAX_BODY - s->body) return limit(p);
  s->body += n; return 0;
}
static int complete(llhttp_t *p) {
  state *s = p->data; s->complete = true; s->messages++; return HPE_PAUSED;
}
static napi_value num(napi_env e, double n) { napi_value v; napi_create_double(e, n, &v); return v; }
static napi_value str(napi_env e, const char *s, size_t n) {
  napi_value v; napi_create_string_latin1(e, s ? s : "", s ? n : 0, &v); return v;
}
static napi_value boolean(napi_env e, bool b) { napi_value v; napi_get_boolean(e, b, &v); return v; }
static void set(napi_env e, napi_value o, const char *k, napi_value v) { napi_set_named_property(e, o, k, v); }
static napi_value fields(napi_env e, state *s, size_t first, size_t end) {
  napi_value a; napi_create_array_with_length(e, end - first, &a);
  for (size_t i = first; i < end; i++) {
    field *f = &s->headers[i]; napi_value pair; napi_create_array_with_length(e, 2, &pair);
    napi_set_element(e, pair, 0, str(e, s->metadata + f->name, f->name_len));
    napi_set_element(e, pair, 1, str(e, s->metadata + f->value, f->value_len));
    napi_set_element(e, a, i - first, pair);
  }
  return a;
